INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3001100, "2024/10/31 12:00:00", 1, 100, 2, 2.1, 0.0, 130011, "ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか", "ヤマト", -416.5, "2030/01/01 14:59:59", 3001);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3001101, "2024/10/31 12:00:00", 4, 101, 2, 5.68, 0.0, 130011, "他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか", "ヤマト", -416.5, "2030/01/01 14:59:59", 3001);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3001102, "2024/10/31 12:00:00", 1, 102, 1, 0.0, 0.0, 130011, "なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。", "ヤマト", -416.5, "2030/01/01 14:59:59", 3001);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3002100, "2024/10/31 12:00:00", 1, 100, 1, 0.0, 0.0, 130211, "え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？", "フブキ", -416.5, "2030/01/01 14:59:59", 3002);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3002101, "2024/10/31 12:00:00", 1, 101, 1, 0.0, 0.0, 130211, "ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡", "フブキ", -416.5, "2030/01/01 14:59:59", 3002);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3002102, "2024/10/31 12:00:00", 5, 102, 2, 8.53, 0.0, 130211, "へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ", "フブキ", -416.5, "2030/01/01 14:59:59", 3002);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3002103, "2024/10/31 12:00:00", 7, 103, 1, 5.67, 0.0, 130211, "なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？", "フブキ", -416.5, "2030/01/01 14:59:59", 3002);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3002104, "2024/10/31 12:00:00", 1, 104, 1, 0.0, 0.0, 130211, "ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？", "フブキ", -416.5, "2030/01/01 14:59:59", 3002);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3002300, "2024/10/31 12:00:00", 3, 300, 3, 0.0, 0.0, 130211, "あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？", "フブキ", -416.5, "2030/01/01 14:59:59", 3004);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3002400, "2024/10/31 12:00:00", 7, 301, 7, 0.0, 0.0, 130211, "ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡", "フブキ", -416.5, "2030/01/01 14:59:59", 3005);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3003200, "2024/10/31 12:00:00", 2, 200, 1, 4.4, 0.0, 130211, "きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪", "フブキ", -416.5, "2030/01/01 14:59:59", 3003);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3003201, "2024/10/31 12:00:00", 7, 201, 7, 0.0, 0.0, 130211, "は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ", "フブキ", -416.5, "2030/01/01 14:59:59", 3003);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3003202, "2024/10/31 12:00:00", 1, 202, 2, 5.6, 0.0, 130211, "お兄さんってば、ぼくがいないと\nほんとザッコザコだよね～\nもっと感謝しろし～♪", "フブキ", -416.5, "2030/01/01 14:59:59", 3003);
